class Solution:
    def countPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        bit = [0] * (n + 1)
        def add(i, d):
            i += 1
            while i <= n:
                bit[i] += d
                i += i & (-i)
        def pre(i):
            i += 1; s = 0
            while i > 0:
                s += bit[i]; i -= i & (-i)
            return s
        pk = [0] * n
        def refresh(p):
            if 1 <= p <= n - 2:
                nv = 1 if nums[p] > nums[p-1] and nums[p] > nums[p+1] else 0
                if nv != pk[p]:
                    add(p, nv - pk[p]); pk[p] = nv
        for p in range(1, n - 1):
            refresh(p)
        res = []
        for q in queries:
            if q[0] == 1:
                lo, hi = max(q[1], 1), min(q[2], n - 2)
                res.append(pre(hi) - pre(lo - 1) if lo <= hi else 0)
            else:
                nums[q[1]] = q[2]
                refresh(q[1] - 1); refresh(q[1]); refresh(q[1] + 1)
        return res

