class Solution {
    int n; vector<int> bit, pk; vector<int>* a;
    void add(int i, int d){ for(++i; i<=n; i+=i&(-i)) bit[i]+=d; }
    int pre(int i){ int s=0; for(++i; i>0; i-=i&(-i)) s+=bit[i]; return s; }
    void refresh(int p){
        if(p<1||p>n-2) return;
        int nv = ((*a)[p]>(*a)[p-1] && (*a)[p]>(*a)[p+1]) ? 1 : 0;
        if(nv!=pk[p]){ add(p, nv-pk[p]); pk[p]=nv; }
    }
public:
    vector<int> countPeaks(vector<int>& nums, vector<vector<int>>& queries){
        n=nums.size(); a=&nums;
        bit.assign(n+1,0); pk.assign(n,0);
        for(int p=1;p<n-1;++p) refresh(p);
        vector<int> res;
        for(auto&q:queries){
            if(q[0]==1){
                int lo=max(q[1],1), hi=min(q[2],n-2);
                res.push_back(lo<=hi ? pre(hi)-pre(lo-1) : 0);
            } else {
                nums[q[1]]=q[2];
                refresh(q[1]-1); refresh(q[1]); refresh(q[1]+1);
            }
        }
        return res;
    }
};

