class Solution {
    int n; int[] bit, pk; int[] a;
    void add(int i, int d){ for(++i; i<=n; i+=i&(-i)) bit[i]+=d; }
    int pre(int i){ int s=0; for(++i; i>0; i-=i&(-i)) s+=bit[i]; return s; }
    void refresh(int p){
        if(p<1||p>n-2) return;
        int nv = (a[p]>a[p-1] && a[p]>a[p+1]) ? 1 : 0;
        if(nv!=pk[p]){ add(p, nv-pk[p]); pk[p]=nv; }
    }
    public int[] countPeaks(int[] nums, int[][] queries){
        n=nums.length; a=nums;
        bit=new int[n+1]; pk=new int[n];
        for(int p=1;p<n-1;++p) refresh(p);
        int[] res = new int[(int)java.util.Arrays.stream(queries).filter(q->q[0]==1).count()];
        int ri=0;
        for(int[] q:queries){
            if(q[0]==1){
                int lo=Math.max(q[1],1), hi=Math.min(q[2],n-2);
                res[ri++] = lo<=hi ? pre(hi)-pre(lo-1) : 0;
            } else {
                nums[q[1]]=q[2];
                refresh(q[1]-1); refresh(q[1]); refresh(q[1]+1);
            }
        }
        return res;
    }
}

