var countPeaks = function(nums, queries) {
    const n = nums.length;
    const bit = new Array(n + 1).fill(0), pk = new Array(n).fill(0);
    const add = (i, d) => { for (++i; i <= n; i += i & (-i)) bit[i] += d; };
    const pre = (i) => { let s = 0; for (++i; i > 0; i -= i & (-i)) s += bit[i]; return s; };
    const refresh = (p) => {
        if (p < 1 || p > n - 2) return;
        const nv = (nums[p] > nums[p-1] && nums[p] > nums[p+1]) ? 1 : 0;
        if (nv !== pk[p]) { add(p, nv - pk[p]); pk[p] = nv; }
    };
    for (let p = 1; p < n - 1; ++p) refresh(p);
    const res = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const lo = Math.max(q[1], 1), hi = Math.min(q[2], n - 2);
            res.push(lo <= hi ? pre(hi) - pre(lo - 1) : 0);
        } else {
            nums[q[1]] = q[2];
            refresh(q[1] - 1); refresh(q[1]); refresh(q[1] + 1);
        }
    }
    return res;
};
